        $words=$a;$rest=[];if(in_array($cmd,['STOICH','LIMITING','YIELD'],true)){if(count(array_filter($a,fn($x)=>$x===':'))!==1)chemError('invalid separator');$i=array_search(':',$a,true);$words=array_slice($a,0,$i);$rest=array_slice($a,$i+1);if(($cmd==='STOICH'&&count($rest)!==2)||($cmd==='YIELD'&&count($rest)!==4))chemError('wrong argument count for '.$cmd);}
        $eq=equation($words,$cmd==='CHECK');['list'=>$list,'r'=>$r,'sign'=>$sign]=$eq;
        if($cmd==='MATRIX'){[$labels,$rows]=compositionMatrix($list,$sign);[$rank,$basis]=nullspace($rows,count($list));$out=['columns: '.implode(' ',array_column($list,'name'))];foreach($rows as $i=>$row)$out[]=$labels[$i].': '.implode(' ',$row);$out[]="rank $rank, nullity ".count($basis);foreach($basis as $v)$out[]='null: '.implode(' ',$v);return $out;}
        if($cmd==='CHECK'){[$labels,$rows]=compositionMatrix($list,$sign);$diff=[];foreach($rows as $i=>$row){$l=$rr=0;foreach($row as $j=>$x){if($j<$r)$l+=$x*$list[$j]['k'];else $rr-=$x*$list[$j]['k'];}if($l!==$rr)$diff[]=$labels[$i].': '.($labels[$i]==='charge'?signedInt($l):$l).' != '.($labels[$i]==='charge'?signedInt($rr):$rr);}if($diff)return array_merge(['not balanced'],$diff);$g=0;foreach($list as $s)$g=gcd($g,$s['k']);return [$g===1?'balanced':"balanced, not in lowest terms (gcd $g)"];}
        $target=$product=-1;$qs=[];
        if($cmd==='DELTAH')foreach($list as $s)if(!isset($this->heats[$s['name']]))chemError('no enthalpy for '.$s['name']);
        if($cmd==='STOICH'){foreach($list as $i=>$s)if($s['name']===$rest[0]){$target=$i;break;}if($target<0)chemError('species '.$rest[0].' not in equation');$qs=[quantity($rest[1])];}
        if($cmd==='LIMITING'){if(count($rest)!==$r)chemError("expected $r masses, got ".count($rest));$qs=array_map('quantity',$rest);}
        if($cmd==='YIELD'){foreach($list as $i=>$s)if($i<$r&&$s['name']===$rest[0]){$target=$i;break;}if($target<0)chemError($rest[0].' is not a reactant');foreach($list as $i=>$s)if($i>=$r&&$s['name']===$rest[2]){$product=$i;break;}if($product<0)chemError($rest[2].' is not a product');$qs=[quantity($rest[1]),quantity($rest[3])];}
