        if($cmd==='DELTAH'){$h=0;foreach($list as $i=>$s)$h-=$sign[$i]*$v[$i]*$this->heats[$s['name']];$out[]='dH = '.ent($h).' kJ ('.($h<0?'exothermic':($h>0?'endothermic':'thermoneutral')).')';return $out;}
        if($cmd==='STOICH'){$d=$v[$target]*$list[$target]['m'];foreach($list as $i=>$s){$x=$qs[0]*$v[$i];$out[]=$s['name'].' '.dec(intdiv($x*1000000,$d),6).' mol '.dec(intdiv($x*$s['m'],$d),3).' g'.gas($s,$x,$d);}return $out;}
        if($cmd==='YIELD'){$t=intdiv($qs[0]*$v[$product]*$list[$product]['m'],$v[$target]*$list[$target]['m']);return array_merge($out,['theoretical '.dec($t,3).' g','actual '.dec($qs[1],3).' g',$t?'yield '.dec(intdiv($qs[1]*10000,$t),2).'%':'yield undefined']);}
        $l=0;for($i=1;$i<$r;$i++)if($qs[$i]*$v[$l]*$list[$l]['m']<$qs[$l]*$v[$i]*$list[$i]['m'])$l=$i;$d=$v[$l]*$list[$l]['m'];$out[]='limiting '.$list[$l]['name'];$out[]='extent '.dec(intdiv($qs[$l]*1000000,$d),6).' mol';for($i=$r;$i<count($list);$i++)$out[]='product '.$list[$i]['name'].' '.dec(intdiv($qs[$l]*$v[$i]*$list[$i]['m'],$d),3).' g'.gas($list[$i],$qs[$l]*$v[$i],$d);for($i=0;$i<$r;$i++)if($i!==$l)$out[]='remaining '.$list[$i]['name'].' '.dec(intdiv($qs[$i]*$d-$qs[$l]*$v[$i]*$list[$i]['m'],$d),3).' g';return $out;
    }
}
$engine=new Chemistry();$n=(int)trim(fgets(STDIN));for($i=0;$i<$n;$i++){try{$out=$engine->execute(rtrim(fgets(STDIN),"\r\n"));}catch(RuntimeException $e){$out=[$e->getMessage()];}foreach($out as $s)echo $s,"\n";}
